 public void Update(Device device,Preferences p){foreach(var pair in values){var metric=device.Metrics.FirstOrDefault(m=>m.Id==pair.Key);pair.Value.Text=metric?.Display(p.Fahrenheit)??"—";pair.Value.ToolTip=metric==null?"Unavailable":Ui.SidebarFullLabel(metric.Label)+" · "+pair.Value.Text;}var primary=device.Metrics.FirstOrDefault(m=>m.Id==primaryId);string display=primary?.Display(p.Fahrenheit)??"—";int split=display.LastIndexOf(' ');number.Text=split<0?display:display[..split];unit.Text=split<0?primary?.Unit??"":display[(split+1)..];meter.Ratio=Ratio(primary);meter.Available=primary?.Value is double v&&double.IsFinite(v);var second=device.Metrics.FirstOrDefault(m=>m.Id!=primaryId&&m.Unit=="%");meter.Secondary=second==null?null:Ratio(second);meter.InvalidateVisual();foreach(var bar in bars){double ratio=Ratio(device.Metrics.FirstOrDefault(m=>m.Id==bar.Id));bar.Fill.Tag=ratio;bar.Fill.Width=Math.Max(0,bar.Track.ActualWidth*ratio);}var plotted=device.Metrics.FirstOrDefault(m=>m.Id==historyId);var points=historyId==null?Array.Empty<HistorySample>():history.Read(deviceId,historyId);double max=plotted?.Unit=="%"?100:plotted?.Unit=="°C"?Math.Max(100,plotted.Maximum):0;var gap=TimeSpan.FromMilliseconds(Math.Max(2500,p.Interval*2.5));line?.SetSamples(points,history.LatestTime,max,gap);samples?.SetSamples(points,history.LatestTime,max);BorderBrush=device.Metrics.Any(m=>m.Value.HasValue&&((m.Unit=="°C"&&m.Value>=p.TempLimit)||(m.Label=="Auslastung"&&m.Value>=p.LoadLimit)))?Ui.Brush("#F47777"):edge;}
 public sealed class BarHistory:FrameworkElement
 {
  private readonly Brush first,last,track;private IReadOnlyList<HistorySample> points=Array.Empty<HistorySample>();private DateTime now;private double maximum;public int SampleCount=>points.Count;
  public BarHistory(string a,string b,string track){first=Ui.Brush(a);last=Ui.Brush(b);this.track=Ui.Brush(track);ClipToBounds=true;}
  public void SetSamples(IReadOnlyList<HistorySample> samples,DateTime time,double max){points=samples;now=time;maximum=max;InvalidateVisual();}
