 }
 private sealed class WidgetMeter:FrameworkElement
 {
  public double Ratio;public bool Available;public double? Secondary;private readonly Brush ink,second,track;private readonly double stroke;private readonly string style;private readonly bool contour;
  public WidgetMeter(string a,string b,string track,double thickness,string style,bool contour){ink=Ui.Brush(a);second=Ui.Brush(b);this.track=Ui.Brush(track);stroke=4*thickness;this.style=style;this.contour=contour;IsHitTestVisible=false;}
  protected override void OnRender(DrawingContext dc){double w=ActualWidth,h=ActualHeight;if(w<3||h<3)return;if(style=="Tube"){double x=w-19;dc.DrawRoundedRectangle(track,null,new Rect(x,4,13,h-8),6,6);if(Available)dc.DrawRoundedRectangle(new LinearGradientBrush(((SolidColorBrush)ink).Color,((SolidColorBrush)second).Color,new Point(0,1),new Point(0,0)),null,new Rect(x,h-4-(h-8)*Ratio,13,(h-8)*Ratio),6,6);return;}if(style=="Strip"){dc.DrawRoundedRectangle(track,null,new Rect(0,2,w,Math.Max(1,h-4)),2,2);if(Available)dc.DrawRoundedRectangle(ink,null,new Rect(0,2,w*Ratio,Math.Max(1,h-4)),2,2);return;}if(style=="Tiles"){for(int i=0;i<16;i++){int x=i%4,y=i/4;double cell=Math.Min(w,h)/4-3;dc.DrawRoundedRectangle(Available&&i<Math.Ceiling(Ratio*16)?new SolidColorBrush(Color.FromArgb(70,((SolidColorBrush)ink).Color.R,((SolidColorBrush)ink).Color.G,((SolidColorBrush)ink).Color.B)):track,null,new Rect(x*(cell+3),y*(cell+3),cell,cell),5,5);}return;}double cx=w/2,cy=h/2,r=Math.Max(2,Math.Min(w,h)/2-7);void Arc(double radius,double from,double sweep,Brush brush,double thickness){if(sweep<=0)return;Point At(double a)=>new(cx+radius*Math.Cos(a*Math.PI/180),cy+radius*Math.Sin(a*Math.PI/180));var f=new PathFigure{StartPoint=At(from)};f.Segments.Add(new ArcSegment(At(from+Math.Min(359.9,sweep)),new Size(radius,radius),0,sweep>180,SweepDirection.Clockwise,true));dc.DrawGeometry(null,new Pen(brush,thickness){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},new PathGeometry(new[]{f}));}double start=style=="Open"?135:-90,total=style=="Open"?270:360;Arc(r,start,total,track,stroke);if(Available){Arc(r,start,total*Ratio,ink,stroke);if(style=="Ring"&&!contour)Arc(r,start+total*Ratio,total*(1-Ratio),second,stroke*.7);}if(contour){Arc(Math.Max(2,r-9),-90,359.9,track,1.7);if(Secondary is double v)Arc(Math.Max(2,r-9),-90,360*v,second,1.7);}}
